//! Parity tests for `enforce_dtypes` and `Pipe.enforce_dtypes`
//! (`tests/fixtures/enforce_dtypes.json`, generated by `tests/fixtures/gen_enforce_dtypes.py`).

mod common;

use common::{cases, compare_frame, decode, decode_frame, load_fixture};
use indexmap::IndexMap;
use meerschaum_kernel::enforce::{
    EnforceOptions, PipeDtypesContext, PipeInput, enforce_dtypes, pipe_enforce_dtypes,
    pipe_get_dtypes, pipe_is_tz_aware,
};
use meerschaum_kernel::value::Value;
use serde_json::Value as J;

fn str_map(j: &J) -> IndexMap<String, String> {
    j.as_object()
        .map(|o| {
            o.iter()
                .map(|(k, v)| (k.clone(), v.as_str().unwrap().to_string()))
                .collect()
        })
        .unwrap_or_default()
}

#[test]
fn enforce_dtypes_parity() {
    let fixture = load_fixture("enforce_dtypes");
    let mut failures = Vec::new();
    let mut checked = 0;
    for case in cases(&fixture) {
        match case["kind"].as_str().unwrap() {
            "enforce_dtypes" => {
                checked += 1;
                let context = format!("{} {} {}", case["frame"], case["dtypes"], case["kwargs"]);
                let df = decode_frame(&case["input"]);
                let dtypes = str_map(&case["dtypes"]);
                let kw = &case["kwargs"];
                let opts = EnforceOptions {
                    explicit_dtypes: str_map(&kw["explicit_dtypes"]),
                    coerce_numeric: kw["coerce_numeric"].as_bool().unwrap_or(false),
                    coerce_timezone: kw["coerce_timezone"].as_bool().unwrap_or(true),
                    strip_timezone: kw["strip_timezone"].as_bool().unwrap_or(false),
                };
                match (enforce_dtypes(&df, &dtypes, &opts), case.get("ok")) {
                    (Ok(out), Some(expected)) => {
                        if let Err(m) = compare_frame(expected, &out, &context) {
                            failures.push(m);
                        }
                    }
                    (Err(_), None) => {}
                    (Ok(_), None) => {
                        failures.push(format!("{context}: expected error {}", case["err"]))
                    }
                    (Err(e), Some(_)) => failures.push(format!("{context}: unexpected error {e}")),
                }
            }
            "pipe_enforce_dtypes" => {
                checked += 1;
                let context = format!("pipe {} {}", case["docs"], case["configured_dtypes"]);
                let configured = str_map(&case["configured_dtypes"]);
                let remote = str_map(&case["remote_dtypes"]);
                let columns = str_map(&case["columns"]);
                let params = &case["parameters"];
                let autoincrement = params["autoincrement"].as_bool().unwrap_or(false);
                let ok = &case["ok"];
                let dtypes = pipe_get_dtypes(&configured, &remote, &columns, autoincrement);
                let explicit =
                    pipe_get_dtypes(&configured, &IndexMap::new(), &columns, autoincrement);
                if serde_json::to_value(&dtypes).unwrap() != ok["pipe_dtypes"] {
                    failures.push(format!(
                        "{context}: get_dtypes {dtypes:?} != {}",
                        ok["pipe_dtypes"]
                    ));
                }
                if serde_json::to_value(&explicit).unwrap() != ok["explicit_dtypes"] {
                    failures.push(format!(
                        "{context}: explicit {explicit:?} != {}",
                        ok["explicit_dtypes"]
                    ));
                }
                // `Pipe.tzinfo` reads `Pipe.dtypes`, i.e. `get_dtypes(infer=True)`.
                let tz_aware = pipe_is_tz_aware(&columns, &dtypes, false, "ts");
                if tz_aware != ok["tzinfo"].is_string() {
                    failures.push(format!("{context}: tzinfo {tz_aware} != {}", ok["tzinfo"]));
                }
                let ctx = PipeDtypesContext {
                    dtypes,
                    explicit_dtypes: explicit,
                    enforce: params["enforce"].as_bool().unwrap_or(true),
                    tz_aware,
                    mixed_numerics: params["mixed_numerics"].as_bool().unwrap_or(true),
                };
                let input = match &case["docs"] {
                    J::Array(docs) => PipeInput::Docs(
                        docs.iter()
                            .map(|d| {
                                d.as_object()
                                    .unwrap()
                                    .iter()
                                    .map(|(k, v)| (k.clone(), decode(v)))
                                    .collect::<IndexMap<String, Value>>()
                            })
                            .collect(),
                    ),
                    J::Object(cols) => PipeInput::Columns(
                        cols.iter()
                            .map(|(k, v)| {
                                (
                                    k.clone(),
                                    v.as_array().unwrap().iter().map(decode).collect(),
                                )
                            })
                            .collect(),
                    ),
                    _ => panic!(),
                };
                match pipe_enforce_dtypes(input, &ctx) {
                    Ok(out) => {
                        if let Err(m) = compare_frame(&ok["df"], &out, &context) {
                            failures.push(m);
                        }
                    }
                    Err(e) => failures.push(format!("{context}: unexpected error {e}")),
                }
            }
            other => panic!("unknown kind {other}"),
        }
    }
    assert!(checked > 150, "too few cases: {checked}");
    // Guard against a vacuous comparator: transformed outputs must differ from their inputs.
    let mut detected = 0;
    for case in cases(&fixture) {
        if case["kind"] == "enforce_dtypes" && case.get("ok").is_some() {
            let input = decode_frame(&case["input"]);
            if compare_frame(&case["ok"], &input, "self-check").is_err() {
                detected += 1;
            }
        }
    }
    assert!(
        detected > 40,
        "comparator detected only {detected} transformed outputs"
    );
    if !failures.is_empty() {
        panic!(
            "{} enforce parity failures:\n{}",
            failures.len(),
            failures.join("\n")
        );
    }
}
